import {fetchCohortJSON} from './current-cohort-loader.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={development:'Original development',supplement:'Supplement',legacy:'Legacy',holdout:'Original holdout',development049:'New development',holdout049:'Fresh holdout',diagnostic049:'Diagnostic variants'};
const student=(id,scope='all')=>'../student-view.html?case='+encodeURIComponent(id)+'&replay=final#/journey/explore'+(scope==='all'?'':'?scope='+scope);
const offer=(p,id,details=false)=>`<li><a href="${h('../student-view.html?case='+encodeURIComponent(id)+'&replay=final#/journey/profession/'+p.id)}">${h(p.title)}</a>${p.degree?' · degree':''}${p.supported?' · specific interests supported':' · '+h(p.band)}${p.r===null?'':` · r ${p.r.toFixed(3)}`}${p.budget?.covers===true?' · budget covered under assumptions':''}${details?`<details><summary>Evidence and exact next questions</summary><ul>${(p.evidence||[]).map(e=>`<li>${h(e.text)}<small> · ${h(e.domain)} · ${h(e.source)} · ${h(e.evidence)}</small></li>`).join('')}</ul>${p.contrary?.length?'<p>Contrary:</p><ul>'+p.contrary.map(e=>'<li>'+h(e.prompt)+'</li>').join('')+'</ul>':''}${p.missing?.length?'<p>Still unclear:</p><ul>'+p.missing.map(e=>'<li>'+h(e.prompt)+'</li>').join('')+'</ul>':''}<p>${h(p.budget?.reason)}</p></details>`:''}</li>`;
export async function mountExplorer053Review(root,{compact=false}={}){if(!root)return;try{const data=await fetchCohortJSON('./explorer-053-data.json.gz');const external=await fetch('./external-validation-053-summary.json').then(r=>r.ok?r.json():null),subjective=await fetch('./explorer-053-subjective-review.json').then(r=>r.ok?r.json():null);const calibration=await fetchCohortJSON('./calibration-054-data.json').catch(()=>null);root.innerHTML=`${calibration?'<aside style="padding:1rem;border:2px solid #45674d;border-radius:12px"><strong>Expanded calibration audit · 0.54</strong><p>160 profiles and307 current Top claims reviewed;82 claims need direct clarification. Original profiles, engine rules and coverage counts are preserved.12 fresh profiles remain outside qualitative review.</p><p><a href="./calibration-review.html">Full cohort, disputed Top claims, omitted directions, exact follow-ups and external comparisons →</a></p></aside>':''}<h2 id="explorer053-heading">Open exploration · 0.53</h2><p>Current results use the saved responses through 0.52 with new open exploration rules. No additional model answers were invented. A separate development review holds16 older inferred responses uncertain; raw responses remain unchanged. All 457 professions remain accessible; broad discovery and supported interest matches are different measures.</p><p><a href="./explorer-validation.html">Comprehensive testing, results and frequency review →</a> · <a href="./docs/questionnaire-overhaul-053.md.html">Flow, scoring, tests and limits →</a></p><div style="overflow:auto"><table><caption>Paired coverage with the same maximum of three supported offers; holdouts separate</caption><thead><tr><th>Cohort</th><th>Models</th><th>Any supported Top: 0.52 → 0.53</th><th>College / graduate Top: 0.52 → 0.53</th><th>Budget covered by 0.53 Top</th><th>Any degree discovery in first12</th></tr></thead><tbody>${data.cohorts.map(c=>`<tr><th>${h(labels[c.phase]||c.phase)}</th><td>${c.n}</td><td>${c.beforeWithTop} → ${c.afterWithTop}</td><td>${c.beforeWithDegreeTop} → ${c.afterWithDegreeTop}</td><td>${c.afterSustainingTop} / ${c.n}</td><td>${c.afterDegreeFirst12} / ${c.n}</td></tr>`).join('')}</tbody></table></div><p>Supported Top is the first three careers meeting specific-interest evidence rules, with no degree or salary bonus. All supported careers remain available. Lifestyle figures require comparable first-paid-stage data; unknown pay is not a failed match.</p>${compact?'':`<section><h3>Testing evidence</h3><ul><li>Software guards: original answers and six scores unchanged; zero out-of-field leakage across all184 public cases. 172 base models and12 diagnostic variants reported separately.</li><li>External agreement: ${external?.local?.correlationComparisons||'77,220'} independently calculated correlations; no numerical errors above tolerance. 18 fresh live official O*NET comparisons; all six-score profiles agree. 724/726 returned career fit labels agree, with two borderline discrepancies retained. These initial0.53 checks did not include a commercial vendor. The linked0.54 audit adds two actual Truity free-result sessions with nonidentical questions and substantial proxy-response limits.</li><li>Additional live service: CareerOneStop30-item assessment, two contrasting synthetic profiles. All12 observed theme scores and41 shared occupation labels agree. Both services use O*NET. Item sampling changes some strong-fit membership; agreement is not predictive validity. <a href="./docs/careeronestop-comparison-053-2026-10-19.md.html">Results, inventory gaps and limitations →</a></li><li>Subjective review: ${subjective?'288 career appearances across24 models reviewed against frozen biography-only expectations.13 development offers received uncertainty holds; four original-holdout offer concerns remain disclosed without tuning. This is one synthetic-case reviewer, not student validation.':'pending report; no subjective accuracy claim yet.'} <a href="./docs/explorer-053-subjective-review.md.html">Review and case judgments →</a></li></ul><p><a href="./external-comparison-053-fixtures.tar.gz" download>Raw external fixtures, crosswalks & screenshots</a> · <a href="./external-validation-053-summary.json">External comparison results · JSON</a> · <a href="./docs/external-validation-053-2026-10-19.md.html">Cross-service protocol and discrepancies</a> · <a href="./docs/testing-program-053.md.html">Comprehensive testing program</a> · <a href="./explorer-053-data.json">Full current public replay · JSON</a></p></section>`}<form id="explorer053-controls"><label>Cohort <select name="cohort"><option value="base">All172 base profiles</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}<option value="all">All184 including diagnostics</option></select></label> <label>Education <select name="education"><option value="all">All routes</option><option value="degree">College and graduate professions only</option></select></label> <label>Find model <input name="query" type="search" placeholder="Name or model ID"></label> <button type="submit">Apply</button></form><p id="explorer053-status" role="status"></p><div id="explorer053-rows"></div>${compact?'':`<section><h3>Current field and profession appearances</h3><p>Per-model deduplication. Fields overlap by reviewed membership. Top = supported first3; Other = remaining first12 discovery, excluding Top; Sustaining = first12 with specific interest support and assessed budget coverage. Zero means absent from these displayed lists, not inaccessible, rejected or missing from inventory.</p><label>Frequency view <select id="explorer053-frequency"><option value="fields">General fields</option><option value="professions">All professions</option><option value="zero">No displayed appearances</option></select></label><div id="explorer053-frequencies" style="overflow:auto"></div></section>`}`;
const form=root.querySelector('#explorer053-controls'),draw=()=>{const v=new FormData(form),cohort=v.get('cohort'),degree=v.get('education')==='degree',q=String(v.get('query')||'').toLowerCase(),rs=data.rows.filter(r=>(cohort==='all'||cohort==='base'&&r.phase!=='diagnostic049'||r.phase===cohort)&&(!q||[r.id,r.name].join(' ').toLowerCase().includes(q))),pick=ps=>ps.filter(p=>!degree||p.degree);root.querySelector('#explorer053-status').textContent=rs.length+' models · '+rs.filter(r=>pick(r.top).length).length+' with supported Top in this education view. '+rs.filter(r=>pick(r.first12).length).length+' with a displayed discovery option.';
root.querySelector('#explorer053-rows').innerHTML=rs.map(r=>`<details style="margin:1rem 0;border:1px solid #c5d0c6;padding:1rem;border-radius:12px"><summary><strong>${h(r.name)}</strong> · ${h(r.id)} · ${h(labels[r.phase])} · ${pick(r.top).length} supported Top · ${r.changed?'changed':'same Top list'}${r.reviewHolds?' · '+r.reviewHolds+' inferred responses held for clarification':''}</summary>${calibration?.rows?.find(c=>c.id===r.id)?'<aside><strong>Current evidence review · 0.54</strong><p>'+h(calibration.rows.find(c=>c.id===r.id).reviewStatus)+'</p><p>'+h(calibration.rows.find(c=>c.id===r.id).reviewed?(calibration.rows.find(c=>c.id===r.id).top.filter(p=>p.verdict==='needs-clarification').map(p=>p.title).join(' · ')||'No majority clarification flag in this review; this is not validated accuracy.'):'Qualitative review not performed for this cohort.')+'</p><a href="./calibration-review.html?query='+encodeURIComponent(r.id)+'">Review this model, omitted directions and follow-up questions →</a></aside>':''}${subjective?.cases?.find(c=>c.id===r.id)?'<aside><strong>Independent blinded review · before development holds</strong><p>'+h(subjective.cases.find(c=>c.id===r.id).assessment)+'</p><p><a href="./docs/explorer-053-subjective-review.md.html">Full judgment, visibility gaps and uncertainty →</a></p></aside>':''}<p><a href="./model-lab.html?case=${r.id}">Full profile and original answers</a> · <a href="${h(student(r.id))}">Interactive current student explorer</a></p><div class="explorer-grid"><section><h3>Previous 0.52 Top · up to3</h3><ul>${pick(r.oldTop).map(p=>'<li>'+h(p.title)+'</li>').join('')||'<li>None</li>'}</ul></section><section><h3>Current supported Top · up to3</h3><ul>${pick(r.top).map(p=>offer(p,r.id,true)).join('')||'<li>No specific support yet. Discovery remains available.</li>'}</ul></section><section><h3>Current first12 discovery · all careers remain browsable</h3><ul>${pick(r.first12).map(p=>offer(p,r.id,true)).join('')||'<li>No displayed careers in this education view. Open explorer with degree filter for all degree connections.</li>'}</ul></section></div><details><summary>Every specifically supported career · ${r.supported.length}</summary><ul>${pick(r.supported).map(p=>offer(p,r.id,true)).join('')}</ul></details><details><summary>Other fields and their career examples</summary>${r.fieldCounts.map(f=>'<p><a href="'+h(student(r.id,f.id))+'">'+h(f.title)+'</a> · '+f.leading.map(p=>h(p.title)).join(' · ')+'</p>').join('')}</details></details>`).join('');
const freq=root.querySelector('#explorer053-frequencies');if(freq){const mode=root.querySelector('#explorer053-frequency').value,all=new Map();for(const o of data.catalog||[])if(!degree||o.degree)all.set(o.id,{...o,top:0,other:0,sustaining:0});for(const r of rs){const tops=new Set(pick(r.top).map(p=>p.id));for(const p of pick(r.top)){const a=all.get(p.id);if(a)a.top++;}for(const p of pick(r.first12)){const a=all.get(p.id);if(!a)continue;if(!tops.has(p.id))a.other++;if(p.supported&&p.budget.covers===true)a.sustaining++;}}
let entries=[...all.values()];if(mode==='zero')entries=entries.filter(x=>!x.top&&!x.other&&!x.sustaining);if(mode==='fields'){entries=data.rows[0].fieldCounts.map(f=>({id:f.id,title:f.title,top:0,other:0,sustaining:0}));for(const f of entries)for(const r of rs){const top=pick(r.top),other=pick(r.first12).filter(p=>!top.some(x=>x.id===p.id));if(top.some(p=>p.fields.includes(f.id)))f.top++;if(other.some(p=>p.fields.includes(f.id)))f.other++;if(pick(r.first12).some(p=>p.fields.includes(f.id)&&p.supported&&p.budget.covers===true))f.sustaining++;}}
entries.sort((a,b)=>b.top-a.top||b.other-a.other||a.title.localeCompare(b.title));freq.innerHTML='<p>'+entries.length+' entries · denominator '+rs.length+' models</p><table><thead><tr><th>Name</th><th>Supported Top</th><th>Other discovery</th><th>Supported and sustains</th></tr></thead><tbody>'+entries.map(x=>'<tr><th>'+h(x.title)+'</th><td>'+x.top+'</td><td>'+x.other+'</td><td>'+x.sustaining+'</td></tr>').join('')+'</tbody></table>';}};
const initial=new URL(location.href).searchParams;if(initial.get('education')==='degree')form.elements.education.value='degree';if([...form.elements.cohort.options].some(o=>o.value===initial.get('cohort')))form.elements.cohort.value=initial.get('cohort');if(initial.get('query'))form.elements.query.value=initial.get('query');
form.addEventListener('submit',e=>{e.preventDefault();draw();});root.querySelector('#explorer053-frequency')?.addEventListener('change',draw);draw();
}catch(e){root.innerHTML='<h2>Open exploration review</h2><p>'+h(e.message)+'. Reload to try again.</p>';}}
